var n=`0553-saloona`;var i=`world-0553`;var a=`QA`;var o=`western-asia`;var s=4;var r=75;var l={en:`Saloona`,ua:`Салюна`};var g={en:`A traditional dish from Qatar, centered on yellow onion, tomato, garlic, lamb. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Катар. Основні складники: жовта цибуля, помідор, часник, ягнятина. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,210,`g`],[`tomato`,340,`g`],[`garlic`,5,`clove`],[`sunflower-oil`,55,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 60 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 60 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:60,i:[[`lamb`,600,`g`],[`potato`,430,`g`],[`carrot`,220,`g`],[`water`,750,`ml`],[`ground-cumin`,5,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:3,i:[[`table-salt`,null,`to_taste`]]}];var u={slug:n,id:i,country:`QA`,region:o,servings:4,minutes:75,title:l,text:g,steps:d};export{a as country,u as default,i as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};